import type { Side } from "./twin";

export type LongPress = { target: HTMLElement; tip: string; side: Side; x: number; y: number };
export const LONG_PRESS_MS = 400;
const SLOP_PX = 10;
const SWALLOW_MS = 700;
const sideOf = (el: HTMLElement): Side => {
  const marked = el.closest<HTMLElement>("[data-side]")?.dataset.side;
  if (marked === "far" || marked === "near") return marked;
  return el.closest("[data-testid='seats-far'], [data-testid='rail-far']") ? "far" : "near";
};
type Hold = { target: HTMLElement; x: number; y: number; timer: number | null; fired: boolean };
type Suppression = { target: HTMLElement; until: number };

export const installPress = (
  root: Document | HTMLElement = document,
  options: { ms?: number; onLong?: (press: LongPress) => void } = {},
): (() => void) => {
  const doc = root instanceof Document ? root : root.ownerDocument;
  const view = doc.defaultView!;
  const holds = new Map<number, Hold>();
  const suppressed = new Map<number, Suppression>();
  const eligible = (target: HTMLElement): boolean => target.isConnected && root.contains(target)
    && !target.closest(':disabled, [aria-disabled="true"], [inert]');
  const clearHold = (id: number): void => {
    const hold = holds.get(id);
    if (!hold) return;
    if (hold.timer !== null) view.clearTimeout(hold.timer);
    holds.delete(id);
    if (![...holds.values()].some((other) => other.target === hold.target)) hold.target.classList.remove("is-holding");
  };
  const reset = (): void => {
    for (const id of holds.keys()) clearHold(id);
    suppressed.clear();
  };
  const down = (event: Event): void => {
    const pointer = event as PointerEvent;
    if (pointer.button !== 0) return;
    clearHold(pointer.pointerId);
    suppressed.delete(pointer.pointerId); // a subsequent intentional tap must work
    const target = pointer.target instanceof Element ? pointer.target.closest<HTMLElement>("[data-tip]") : null;
    if (!target || !eligible(target)) return;
    const hold: Hold = { target, x: pointer.clientX, y: pointer.clientY, timer: null, fired: false };
    holds.set(pointer.pointerId, hold);
    target.classList.add("is-holding");
    hold.timer = view.setTimeout(() => {
      hold.timer = null;
      target.classList.remove("is-holding");
      if (!eligible(target)) { clearHold(pointer.pointerId); return; }
      hold.fired = true;
      suppressed.set(pointer.pointerId, { target, until: Infinity });
      const press: LongPress = { target, tip: target.dataset.tip ?? "", side: sideOf(target), x: hold.x, y: hold.y };
      target.dispatchEvent(new CustomEvent<LongPress>("ui:longpress", { bubbles: true, detail: press }));
      options.onLong?.(press);
    }, options.ms ?? LONG_PRESS_MS);
  };
  const move = (event: Event): void => {
    const pointer = event as PointerEvent;
    const hold = holds.get(pointer.pointerId);
    if (hold && !hold.fired && Math.hypot(pointer.clientX - hold.x, pointer.clientY - hold.y) > SLOP_PX) clearHold(pointer.pointerId);
  };
  const up = (event: Event): void => {
    const id = (event as PointerEvent).pointerId;
    const blocked = suppressed.get(id);
    if (blocked) blocked.until = Date.now() + SWALLOW_MS;
    clearHold(id);
  };
  const cancel = (event: Event): void => {
    const id = (event as PointerEvent).pointerId;
    clearHold(id);
    suppressed.delete(id);
  };
  const click = (event: Event): void => {
    // Keyboard​ activation has detail=0 and must not inherit a pointer's suppression.
    if ((event as MouseEvent).detail === 0) return;
    for (const [id, blocked] of suppressed) {
      if (Date.now() > blocked.until) { suppressed.delete(id); continue; }
      if (blocked.target.contains(event.target as Node)) {
        event.stopImmediatePropagation();
        event.preventDefault();
        suppressed.delete(id);
        return;
      }
    }
  };
  const menu = (event: Event): void => {
    if (event.target instanceof Element && event.target.closest("[data-tip]")) event.preventDefault();
  };
  const visibility = (): void => { if (doc.hidden) reset(); };
  const listeners = { pointerdown: down, pointermove: move, pointerup: up, pointercancel: cancel, lostpointercapture: cancel,
    contextmenu: menu };
